targets.rawSql:
SELECT count(*) FROM gold.feed WHERE coalesce(nullif(regions, '{}'), '{other}') && ARRAY[$region]::text[]
  AND company_tier IN ($tier)
  AND ('__all' IN ($role) OR role IN ($role))
  AND ('__all' IN ($seniority) OR seniority IN ($seniority))
  AND coalesce(score, 0) * 100 >= ${min_match:raw}
  AND first_seen > now() - interval '1 day' * ${new:raw}

SELECT 100 * percentile_cont(0.5) WITHIN GROUP (ORDER BY score) FROM gold.feed WHERE coalesce(nullif(regions, '{}'), '{other}') && ARRAY[$region]::text[]
  AND company_tier IN ($tier)
  AND ('__all' IN ($role) OR role IN ($role))
  AND ('__all' IN ($seniority) OR seniority IN ($seniority))
  AND coalesce(score, 0) * 100 >= ${min_match:raw}
  AND first_seen > now() - interval '1 day' * ${new:raw}
